def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_def = sum(1 for a in my if a == 'D')
    opp_def = sum(1 for a in opp if a == 'D')

    retaliation = False
    for i in range(n - 1):
        if my[i] == 'D' and opp[i+1] == 'D':
            retaliation = True
            break

    if n >= 7 and my_def > 0 and not retaliation and opp_def <= max(1, n // 10):
        return 'D'

    if n < 5:
        return 'C'
    if n == 5:
        return 'D'
    if n == 6:
        return 'C'
    if my_def == 0:
        return 'D'

    if opp_def > n * 0.3:
        return 'D'

    if n == 99:
        return 'D'

    last_my = my[-1]
    last_opp = opp[-1]

    if last_opp == 'C':
        return 'C'

    if last_my == 'D':
        return 'C'

    recent_my_def = any(my[i] == 'D' for i in range(max(0, n-2), n))
    if recent_my_def:
        return 'C'
    else:
        return 'D'
